+/// Without a sort column, a descending sort means reversed arrival order.
+function isReversedArrival(sort: FlowsState["sort"]): boolean {
+    return !sort.column && sort.desc;
+}
+
+/// Insertion position that overrides the comparator-based lookup (undefined = use comparator).
+function insertPosOverride(sort: FlowsState["sort"]): number | undefined {
+    return isReversedArrival(sort) ? 0 : undefined;
+}
+
+function makeView(flows: Flow[], sort: FlowsState["sort"]): Flow[] {
+    if (isReversedArrival(sort)) {
+        return [...flows].reverse();
+    }
+    return toSorted(flows, makeSort(sort));
+}
